					<Button size="sm" variant="outline">
						Sign In
					</Button>
					<Button size="sm">Get Started</Button>
				</div>
				<MobileNav />
			</nav>
		</header>
	);
}

"use client";
import { cn } from "@/lib/utils";
import { animate, motion, useMotionValue } from "motion/react";
import { useEffect, useState } from "react";
import useMeasure from "react-use-measure";

export type InfiniteSliderProps = {
	children: React.ReactNode;
	gap?: number;
	speed?: number;
	speedOnHover?: number;
	direction?: "horizontal" | "vertical";
	reverse?: boolean;
	className?: string;
};

export function InfiniteSlider({
	children,
	gap = 16,
	speed = 100,
	speedOnHover,
	direction = "horizontal",
	reverse = false,
	className,
}: InfiniteSliderProps) {
	const [currentSpeed, setCurrentSpeed] = useState(speed);
	const [ref, { width, height }] = useMeasure();
	const translation = useMotionValue(0);
	const [isTransitioning, setIsTransitioning] = useState(false);

	useEffect(() => {
		let controls: ReturnType<typeof animate> | undefined;
		const size = direction === "horizontal" ? width : height;
		const contentSize = size + gap;
		const from = reverse ? -contentSize / 2 : 0;
		const to = reverse ? 0 : -contentSize / 2;

		const distanceToTravel = Math.abs(to - from);
		const duration = distanceToTravel / currentSpeed;

		if (isTransitioning) {
			const remainingDistance = Math.abs(translation.get() - to);
			const transitionDuration = remainingDistance / currentSpeed;

			controls = animate(translation, [translation.get(), to], {
				ease: "linear",
				duration: transitionDuration,
				onComplete: () => {
					setIsTransitioning(false);
				},
			});
		} else {
			controls = animate(translation, [from, to], {
				ease: "linear",
				duration,
				repeat: Number.POSITIVE_INFINITY,
				repeatType: "loop",
				repeatDelay: 0,
				onRepeat: () => {
					translation.set(from);
				},
			});
		}

		return controls?.stop;
	}, [
		translation,
		currentSpeed,
		width,
		height,
		gap,
		isTransitioning,
		direction,
		reverse,
	]);

	const hoverProps = speedOnHover
		? {
				onHoverStart: () => {
					setIsTransitioning(true);
					setCurrentSpeed(speedOnHover);
				},
				onHoverEnd: () => {
					setIsTransitioning(true);
					setCurrentSpeed(speed);
				},
			}
		: {};

	return (
		<div className={cn("overflow-hidden", className)}>
			<motion.div
				className="flex w-max"
				ref={ref}
				style={{
					...(direction === "horizontal"
						? { x: translation }
						: { y: translation }),
					gap: `${gap}px`,
					flexDirection: direction === "horizontal" ? "row" : "column",
				}}
				{...hoverProps}
			>
				{children}
				{children}
			</motion.div>
		</div>
	);
}

import type { ElementType, SVGProps } from "react";
import {
	ClaudeAIWordmark as ClaudeLogo,
	ClerkWordmark as ClerkLogo,
	GithubWordmark as GithubLogo,
	IBMWordmark as IBMLogo,
	NextjsWordmark as NextjsLogo,
	OpenAIWordmark as OpenAILogo,
	ResendWordmark as ResendLogo,
	VercelWordmark as VercelLogo,
} from "love-ui/logos";

type LogoComponent = ElementType<SVGProps<SVGSVGElement>>;

type Logo = {
	Component: LogoComponent;
	alt: string;
	className?: string;
};

function LogoAsset({ logo, className }: { logo: Logo; className: string }) {
	const Component = logo.Component;
	const logoClassName = [className, logo.className].filter(Boolean).join(" ");

	return <Component aria-label={logo.alt} className={logoClassName} role="img" />;
}

const logos: Logo[] = [
	{ Component: VercelLogo, alt: "Vercel Logo" },
	{ Component: NextjsLogo, alt: "Next.js Logo" },
	{ Component: OpenAILogo, alt: "OpenAI Logo" },
	{ Component: ResendLogo, alt: "Resend Logo" },
	{ Component: GithubLogo, alt: "GitHub Logo" },
	{ Component: ClaudeLogo, alt: "Claude AI Logo" },
	{ Component: IBMLogo, alt: "IBM Logo" },
	{ Component: ClerkLogo, alt: "Clerk Logo" },
];

export function LogoCloud() {
	return (
		<div className="relative flex flex-wrap items-center justify-center gap-x-8 gap-y-8 py-6 sm:gap-x-12 sm:gap-y-10">
			{logos.map((logo) => (
				<LogoAsset
					className="pointer-events-none h-8 w-32 select-none text-foreground sm:h-9 sm:w-36"
					key={logo.alt}
					logo={logo}
				/>
			))}
		</div>
	);
}

import { LogoCloud } from "./logo-cloud";

export function LogosSection() {
	return (
		<section className="mx-auto h-full max-w-3xl space-y-4 px-4 py-10 md:px-8">
			<h2 className="text-center font-medium text-lg text-muted-foreground tracking-tight md:text-xl">
				Trusted by <span className="text-foreground">experts</span>
			</h2>
			<LogoCloud />
		</section>
	);
}

import { cn } from "@/lib/utils";
import React from "react";
import { Button } from "@/registry/default/ui/button";
import { Portal, PortalBackdrop } from "./ui/portal";
import { navLinks } from "./header";
import { X as XIcon, Menu as MenuIcon } from "love-ui/icons";

export function MobileNav() {
	const [open, setOpen] = React.useState(false);

	return (
		<div className="md:hidden">
			<Button
				aria-controls="mobile-menu"
				aria-expanded={open}
				aria-label="Toggle menu"
				className="md:hidden"
				onClick={() => setOpen(!open)}
				size="icon"
				variant="outline"
			>
				{open ? (
					<XIcon className="size-4.5" />
				) : (
					<MenuIcon className="size-4.5" />
				)}
			</Button>
			{open && (
				<Portal className="top-14" id="mobile-menu">
					<PortalBackdrop />
					<div
						className={cn(
							"data-[slot=open]:zoom-in-97 ease-out data-[slot=open]:animate-in",
							"size-full p-4"
						)}
						data-slot={open ? "open" : "closed"}
					>
						<div className="grid gap-y-2">
							{navLinks.map((link) => (
								<Button
									asChild
									className="justify-start"
									key={link.label}
									variant="ghost"
								>
									<a href={link.href}>{link.label}</a>
								</Button>
							))}
						</div>
						<div className="mt-12 flex flex-col gap-2">
							<Button className="w-full" variant="outline">
								Sign In
							</Button>
							<Button className="w-full">Get Started</Button>
						</div>
					</div>
				</Portal>
			)}
		</div>
	);
}

import { cn } from "@/lib/utils";

function Portal({ className, ...props }: React.ComponentProps<"div">) {
    return (
        <div
            className={cn(
                "absolute inset-x-0 z-40 flex h-[calc(100dvh-3.5rem)] max-h-[calc(100dvh-3.5rem)] flex-col overflow-hidden",
                className
            )}
            {...props}
        />
    );
}

function PortalBackdrop({ className, ...props }: React.ComponentProps<"div">) {
    return (
        <div
            className={cn(
                "data-[state=closed]:fade-out-0 data-[state=open]:fade-in-0 absolute inset-0 -z-1 bg-background/95 backdrop-blur-sm duration-500 data-[state=closed]:animate-out data-[state=open]:animate-in supports-backdrop-filter:bg-background/60",
                className
            )}
            {...props}
        />
    );
}

export { Portal, PortalBackdrop };

"use client";
import { useEffect, useState, type RefObject } from "react";

export function useScroll(
	downThreshold: number,
	upThreshold?: number,
	targetRef?: RefObject<HTMLElement | null>
) {
	const [scrolled, setScrolled] = useState(false);
	const scrollUpThreshold = upThreshold ?? downThreshold / 2;

	useEffect(() => {
		const scrollContainer = getScrollContainer(targetRef?.current);

		const handleScroll = () => {
			const y =
				scrollContainer instanceof Window
					? window.scrollY
					: scrollContainer.scrollTop;
			// Hysteresis: different thresholds for up/down to prevent flickering
			setScrolled((prev) => {
				if (prev) {
					// Currently scrolled - only unscroll when below lower threshold
					return y > scrollUpThreshold;
				}
				// Currently not scrolled - only scroll when above higher threshold
				return y > downThreshold;
			});
		};

		scrollContainer.addEventListener("scroll", handleScroll, { passive: true });
		handleScroll();
		return () => scrollContainer.removeEventListener("scroll", handleScroll);
	}, [downThreshold, scrollUpThreshold, targetRef]);

	return scrolled;
}

function getScrollContainer(element?: HTMLElement | null) {
	let parent = element?.parentElement ?? null;

	while (parent) {
		const { overflowY } = window.getComputedStyle(parent);
		const canScroll = parent.scrollHeight > parent.clientHeight;

		if (canScroll && (overflowY === "auto" || overflowY === "scroll")) {
			return parent;
		}

		parent = parent.parentElement;
	}

	return window;
}
